props.css_template:
.recent-chat-row { display: flex; align-items: center; gap: 4px;
  width: 100%; min-width: 0; border-radius: 10px; margin: 3px 0; }
.recent-chat-row:hover, .recent-chat-row.is-selected {
  background: var(--button-secondary-background-fill-hover, #e8eef9); }
.recent-chat-row button { border: 0 !important; background: transparent !important;
  box-shadow: none !important; color: inherit;
  cursor: pointer; font: inherit; border-radius: 8px; min-height: 36px; }
.recent-chat-title { flex: 1; min-width: 0; padding: 7px 8px;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap; text-align: left; }
.recent-chat-remove { flex: 0 0 30px; padding: 0 !important; font-size: 20px !important;
  line-height: 1; opacity: .7; }
.recent-chat-remove:hover { opacity: 1; color: #bc3030; }
.recent-chat-row button:focus-visible {
  outline: 2px solid #4263eb; outline-offset: 1px; }

props.js_on_load:
element.addEventListener('click', (event) => {
  const target = event.target.closest('button[data-chat-action]');
  if (!target || !element.contains(target)) return;
  event.preventDefault();
  event.stopPropagation();
  trigger(target.dataset.chatAction === 'remove' ? 'delete' : 'select', {
    conversation_id: target.dataset.conversationId
  });
});
